import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class CrystalCacheSystem {

    static class CrystalCache<K, V> {
        private final Map<K, V> relics;
        private final ReadWriteLock lock = new ReentrantReadWriteLock();

        CrystalCache(Map<K, V> initialRelics) {
            this.relics = initialRelics;
        }

        void put(K key, V value) {
            lock.writeLock().lock();
            try {
                relics.put(key, value);
                System.out.println(Thread.currentThread().getName() + " enshrined relic: " + key + " -> " + value);
            } finally {
                lock.writeLock().unlock();
            }
        }

        V remove(K key) {
            lock.writeLock().lock();
            try {
                V removed = relics.remove(key);
                System.out.println(Thread.currentThread().getName() + " banished relic: " + key);
                return removed;
            } finally {
                lock.writeLock().unlock();
            }
        }

        void putAll(Map<? extends K, ? extends V> otherRelics) {
            lock.writeLock().lock();
            try {
                relics.putAll(otherRelics);
                System.out.println(Thread.currentThread().getName() + " enshrined multiple relics");
            } finally {
                lock.writeLock().unlock();
            }
        }

        void clear() {
            lock.writeLock().lock();
            try {
                relics.clear();
                System.out.println(Thread.currentThread().getName() + " cleared the cache");
            } finally {
                lock.writeLock().unlock();
            }
        }

        V get(K key) {
            lock.readLock().lock();
            try {
                V value = relics.get(key);
                System.out.println(Thread.currentThread().getName() + " divined relic: " + key + " -> " + value);
                return value;
            } finally {
                lock.readLock().unlock();
            }
        }

        int size() {
            lock.readLock().lock();
            try {
                return relics.size();
            } finally {
                lock.readLock().unlock();
            }
        }

        boolean isEmpty() {
            lock.readLock().lock();
            try {
                return relics.isEmpty();
            } finally {
                lock.readLock().unlock();
            }
        }

        boolean containsKey(K key) {
            lock.readLock().lock();
            try {
                return relics.containsKey(key);
            } finally {
                lock.readLock().unlock();
            }
        }

        boolean containsValue(V value) {
            lock.readLock().lock();
            try {
                return relics.containsValue(value);
            } finally {
                lock.readLock().unlock();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, String> initialRelics = new HashMap<>();
        initialRelics.put("amulet", "protection");
        initialRelics.put("orb", "foresight");

        CrystalCache<String, String> cache = new CrystalCache<>(initialRelics);

        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable enchanterWriter = () -> {
            for (int i = 1; i <= 5; i++) {
                cache.put("relic" + i, "power" + i);
                try {
                    Thread.sleep(30);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            cache.remove("relic1");
        };

        Runnable seerReaderOne = () -> {
            for (int i = 0; i < 5; i++) {
                cache.get("amulet");
                System.out.println(Thread.currentThread().getName() + " size: " + cache.size());
                try {
                    Thread.sleep(20);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable seerReaderTwo = () -> {
            for (int i = 0; i < 5; i++) {
                System.out.println(Thread.currentThread().getName() + " containsKey(orb): " + cache.containsKey("orb"));
                System.out.println(Thread.currentThread().getName() + " isEmpty: " + cache.isEmpty());
                try {
                    Thread.sleep(25);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        executor.submit(enchanterWriter);
        executor.submit(seerReaderOne);
        executor.submit(seerReaderTwo);

        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);

        System.out.println("Final cache size: " + cache.size());
        System.out.println("Contains 'orb': " + cache.containsValue("foresight"));
    }
}

