        private final ReadWriteLock lock = new ReentrantReadWriteLock();

        EnchantedRegistry(Map<K, V> initialArtifacts) {
            this.artifacts = initialArtifacts;
        }

        void put(K key, V value) {
            lock.writeLock().lock();
            try {
                artifacts.put(key, value);
                System.out.println(Thread.currentThread().getName() + " crafted artifact: " + key + " -> " + value);
            } finally {
                lock.writeLock().unlock();
            }
        }

        V remove(K key) {
            lock.writeLock().lock();
            try {
                V removed = artifacts.remove(key);
                System.out.println(Thread.currentThread().getName() + " dismantled artifact: " + key);
                return removed;
            } finally {
                lock.writeLock().unlock();
            }
        }

        void putAll(Map<? extends K, ? extends V> otherArtifacts) {
            lock.writeLock().lock();
            try {
                artifacts.putAll(otherArtifacts);
                System.out.println(Thread.currentThread().getName() + " crafted multiple artifacts");
            } finally {
                lock.writeLock().unlock();
            }
        }

        void clear() {
            lock.writeLock().lock();
            try {
                artifacts.clear();
                System.out.println(Thread.currentThread().getName() + " cleared the registry");
            } finally {
                lock.writeLock().unlock();
            }
        }

        V get(K key) {
            lock.readLock().lock();
            try {
                V value = artifacts.get(key);
                System.out.println(Thread.currentThread().getName() + " observed artifact: " + key + " -> " + value);
                return value;
            } finally {
                lock.readLock().unlock();
            }
        }

        int size() {
            lock.readLock().lock();
            try {
                return artifacts.size();
            } finally {
                lock.readLock().unlock();
            }
        }

        boolean isEmpty() {
            lock.readLock().lock();
            try {
                return artifacts.isEmpty();
            } finally {
                lock.readLock().unlock();
            }
        }

        boolean containsKey(K key) {
            lock.readLock().lock();
            try {
                return artifacts.containsKey(key);
            } finally {
                lock.readLock().unlock();
            }
        }

        boolean containsValue(V value) {
            lock.readLock().lock();
            try {
                return artifacts.containsValue(value);
            } finally {
                lock.readLock().unlock();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, String> initialArtifacts = new HashMap<>();
        initialArtifacts.put("chalice", "renewal");
        initialArtifacts.put("blade", "sharpness");

        EnchantedRegistry<String, String> registry = new EnchantedRegistry<>(initialArtifacts);

        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable crafterWriter = () -> {
            for (int i = 1; i <= 5; i++) {
                registry.put("artifact" + i, "essence" + i);
                try {
                    Thread.sleep(30);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            registry.remove("artifact1");
        };

        Runnable observerReaderOne = () -> {
            for (int i = 0; i < 5; i++) {
                registry.get("chalice");
                System.out.println(Thread.currentThread().getName() + " size: " + registry.size());
                try {
                    Thread.sleep(20);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable observerReaderTwo = () -> {
            for (int i = 0; i < 5; i++) {
                System.out.println(Thread.currentThread().getName() + " containsKey(blade): " + registry.containsKey("blade"));
                System.out.println(Thread.currentThread().getName() + " isEmpty: " + registry.isEmpty());
                try {
                    Thread.sleep(25);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        executor.submit(crafterWriter);
        executor.submit(observerReaderOne);
        executor.submit(observerReaderTwo);

        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);

        System.out.println("Final registry size: " + registry.size());
