public class CelestialGriffinTracker {

    private final StarlightMap<String, MutableGem> starlightMap;

    public CelestialGriffinTracker(StarlightMap<String, MutableGem> initialMap) {
        this.starlightMap = deepForge(initialMap);
    }

    public synchronized StarlightMap<String, MutableGem> getStarlights() {
        StarlightMap<String, MutableGem> copy = deepForge(starlightMap);
        StarlightMap<String, MutableGem> unmodifiable = new StarlightMap<>();
        for (Map.Entry<String, MutableGem> entry : copy.entrySet()) {
            unmodifiable.put(entry.getKey(), entry.getValue());
        }
        return unmodifiableStarlightMap(unmodifiable);
    }

    private static StarlightMap<String, MutableGem> unmodifiableStarlightMap(StarlightMap<String, MutableGem> map) {
        Map<String, MutableGem> unmod = Collections.unmodifiableMap(map);
        StarlightMap<String, MutableGem> result = new StarlightMap<String, MutableGem>() {
            @Override
            public MutableGem put(String key, MutableGem value) {
                throw new UnsupportedOperationException();
            }

            @Override
            public MutableGem remove(Object key) {
                throw new UnsupportedOperationException();
            }

            @Override
            public void clear() {
                throw new UnsupportedOperationException();
            }

            @Override
            public void putAll(Map<? extends String, ? extends MutableGem> m) {
                throw new UnsupportedOperationException();
            }
        };
        for (Map.Entry<String, MutableGem> entry : unmod.entrySet()) {
            java.util.HashMap<String, MutableGem> backdoor = result;
            backdoor.put(entry.getKey(), entry.getValue());
        }
        return result;
    }

    public synchronized MutableGem getGem(String rune) {
        MutableGem gem = starlightMap.get(rune);
        if (gem == null) {
            return null;
        }
        return new MutableGem(gem);
    }

    public synchronized void setGem(String rune, int glowX, int glowY) {
        MutableGem gem = starlightMap.get(rune);
        if (gem == null) {
            throw new IllegalArgumentException("Rune not present: " + rune);
        }
        gem.setGlowX(glowX);
        gem.setGlowY(glowY);
    }

    private static StarlightMap<String, MutableGem> deepForge(StarlightMap<String, MutableGem> source) {
        StarlightMap<String, MutableGem> forged = new StarlightMap<>();
        for (Map.Entry<String, MutableGem> entry : source.entrySet()) {
            forged.put(entry.getKey(), new MutableGem(entry.getValue()));
        }
        return forged;
    }

    public static void main(String[] args) throws InterruptedException {
        StarlightMap<String, MutableGem> initialMap = new StarlightMap<>();
        initialMap.put("griffin-alpha", new MutableGem(1, 1));
        initialMap.put("griffin-beta", new MutableGem(2, 2));
        initialMap.put("griffin-gamma", new MutableGem(3, 3));

        final CelestialGriffinTracker tracker = new CelestialGriffinTracker(initialMap);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updaterTask = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 5; i++) {
                    tracker.setGem("griffin-alpha", i, i * 2);
                    tracker.setGem("griffin-beta", i + 10, i + 20);
                    try {
                        Thread.sleep(10);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        };

        Runnable readerTask = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 5; i++) {
                    MutableGem gem = tracker.getGem("griffin-alpha");
                    System.out.println("Reader sees griffin-alpha: " + gem);
                    StarlightMap<String, MutableGem> snapshot = tracker.getStarlights();
                    System.out.println("Snapshot: " + snapshot);
                    try {
                        Thread.sleep(10);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        };

        executor.submit(updaterTask);
        executor.submit(readerTask);

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        try {
            tracker.setGem("griffin-delta", 0, 0);
        } catch (IllegalArgumentException e) {
            System.out.println("Expected exception: " + e.getMessage());
        }

        System.out.println("Final state: " + tracker.getStarlights());
    }
}

