import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V put(K key, V value) {
        lock.writeLock().lock();
        try {
            return map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V remove(Object key) {
        lock.writeLock().lock();
        try {
            return map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        lock.writeLock().lock();
        try {
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V get(Object key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        lock.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        lock.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final ReadWriteMap<String, Integer> map = new ReadWriteMap<String, Integer>(new HashMap<String, Integer>());

        Thread writer = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                map.put("key-" + i, i);
            }
        }, "writer-thread");

        Thread reader1 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                map.get("key-" + i);
            }
        }, "reader-thread-1");

        Thread reader2 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                map.containsKey("key-" + i);
            }
        }, "reader-thread-2");

        writer.start();
        writer.join();

        reader1.start();
        reader2.start();
        reader1.join();
        reader2.join();

        System.out.println("Map size: " + map.size());
    }
}

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

public class BoundedHashSet<T> {
    private final Set<T> set;
    private final Semaphore sem;

    public BoundedHashSet(int bound) {
        this.set = Collections.synchronizedSet(new HashSet<T>());
        this.sem = new Semaphore(bound);
    }

    public boolean add(T o) throws InterruptedException {
        sem.acquire();
        boolean wasAdded = false;
        try {
            wasAdded = set.add(o);
            return wasAdded;
        } finally {
            if (!wasAdded) {
                sem.release();
            }
        }
    }

    public boolean remove(Object o) {
        boolean wasRemoved = set.remove(o);
        if (wasRemoved) {
            sem.release();
        }
        return wasRemoved;
    }

    public static void main(String[] args) throws InterruptedException {
        final BoundedHashSet<Integer> boundedSet = new BoundedHashSet<Integer>(3);
        ExecutorService executor = Executors.newFixedThreadPool(4);

        for (int i = 0; i < 4; i++) {
            final int value = i;
            executor.execute(() -> {
                try {
                    boolean added = boundedSet.add(value);
                    System.out.println(Thread.currentThread().getName() + " added " + value + ": " + added);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Set contents: " + boundedSet.set);
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

public class BetterAttributeStore {
    private final Map<String, String> attributes = new HashMap<String, String>();

    public boolean userLocationMatches(String name, String regexp) {
        String key = "users." + name + ".location";
        String location;
        synchronized (this) {
            location = attributes.get(key);
        }
        if (location == null) {
            return false;
        }
        return Pattern.matches(regexp, location);
    }

    public synchronized void setAttribute(String key, String value) {
        attributes.put(key, value);
    }

    public static void main(String[] args) throws InterruptedException {
        final BetterAttributeStore store = new BetterAttributeStore();
        store.setAttribute("users.alice.location", "New York");
        store.setAttribute("users.bob.location", "London");

        Runnable task = () -> {
            boolean matches = store.userLocationMatches("alice", "New.*");
            System.out.println(Thread.currentThread().getName() + " match result: " + matches);
        };

        Thread t1 = new Thread(task, "checker-1");
        Thread t2 = new Thread(task, "checker-2");

        t1.start();
        t2.start();
        t1.join();
        t2.join();
    }
}
